const PAT = $env.AIRTABLE_PAT;
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tblQkG1DeczNyWsyM';
const MENU_TABLE_ID = 'tbltYZZMUsQg5rxPC';
const MENU_CACHE_TTL = 30 * 60 * 1000; // 30 minutes

const TWILIO_SID = 'REDACTED__SET_AS_N8N_ENV_VAR_TWILIO_SID';
const TWILIO_AUTH = 'REDACTED__SET_AS_N8N_ENV_VAR_TWILIO_AUTH';
const TWILIO_FROM = '+13136311176';
const TWILIO_TO = ''; // restaurant notification number -- set once Hassan confirms

const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') args = JSON.parse(args);

const callId = body?.message?.call?.id || '';
const callerPhone = body?.message?.call?.customer?.number || '';

const customerName = args.customerName || 'Unknown';
const location = args.location || '';
const language = args.language || 'en';
const items = args.items || [];
const pickupTime = args.pickupTime || 'ASAP';

// -- Load menu prices (cached -- refreshed every 30 min, same pattern as vapi_get_menu_info) --
const cache = $getWorkflowStaticData('global');
const now = Date.now();
let menu = cache.menu;
if (!menu || (now - menu.ts) > MENU_CACHE_TTL) {
  let records = [];
  let offset;
  do {
    const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + MENU_TABLE_ID +
      '?fields[]=Item%20Name&fields[]=Price&pageSize=100' +
      (offset ? '&offset=' + offset : '');
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
    records = records.concat(res.records || []);
    offset = res.offset;
  } while (offset);

  menu = {
    ts: now,
    prices: records.map(r => ({ name: r.fields['Item Name'] || '', price: Number(r.fields['Price']) || 0 }))
  };
  cache.menu = menu;
}

// -- Normalize + fuzzy-match helper for looking up menu prices --
function normalize(s) {
  return (s || '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\b(smoothie|wrap|bowl|salad|juice|burrito)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function findPrice(name, menuItemId) {
  const candidates = [name, menuItemId].filter(Boolean).map(normalize).filter(Boolean);

  for (const c of candidates) {
    const exact = menu.prices.find(m => normalize(m.name) === c);
    if (exact) return exact.price;
  }
  for (const c of candidates) {
    const partial = menu.prices.find(m => {
      const mn = normalize(m.name);
      return mn && (mn.includes(c) || c.includes(mn));
    });
    if (partial) return partial.price;
  }
  return null;
}

// -- Build human-readable items list (with modifications) and order total --
let total = 0;
const itemsText = items.map(i => {
  const qty = i.quantity || 1;
  let line = qty + 'x ' + i.name;

  const extras = [];
  if (i.notes) extras.push(i.notes);
  if (i.modifiers && i.modifiers.length) extras.push(i.modifiers.join(', '));
  if (extras.length) line += ' (' + extras.join(', ') + ')';

  const price = (typeof i.price === 'number') ? i.price : findPrice(i.name, i.menuItemId);
  if (price != null) {
    total += price * qty;
    line += ' - $' + price.toFixed(2);
  }

  return line;
}).join('\n');

const orderText = itemsText || args.orderSummary || '';
const estimatedTotal = (typeof args.estimatedTotal === 'number')
  ? args.estimatedTotal
  : Math.round(total * 100) / 100;

// -- Compute next Ticket ID (previous max + 1, starting at 1000) --
let ticketId = 1000;
try {
  const tRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID +
      '?maxRecords=1&sort%5B0%5D%5Bfield%5D=Ticket%20ID&sort%5B0%5D%5Bdirection%5D=desc&fields%5B%5D=Ticket%20ID',
    headers: { Authorization: 'Bearer ' + PAT }
  });
  const top = tRes.records && tRes.records[0];
  const topTicket = top && top.fields['Ticket ID'];
  if (typeof topTicket === 'number') ticketId = topTicket + 1;
} catch (e) {
  // fall back to default starting ticket number if the lookup fails
}

// Write to Airtable
const record = {
  fields: {
    'fld0ueP1iMC8t8w3H': customerName,
    'fld5t3J3iVgrZMWqN': orderText,
    'fldzT5EEtMrmx2Smp': location,
    'fldHWx4jyAI8ih68i': callerPhone,
    'fldZpM4vLB5ryl2Eg': estimatedTotal,
    'fld5UKntch8ztKHyE': language,
    'fldBpeYTgz9dBVbwH': callId,
    'fldtavp7YkLSt1OZr': new Date().toISOString(),
    'flditfDYa3x08ZaWR': JSON.stringify(args, null, 2),
    'fldGDlt6DNHF1iH4m': 'New',
    'fldIbTNi6PPYBT3po': ticketId,
    'fldHGqRFXOG12pdfF': pickupTime
  }
};

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID,
  headers: { Authorization: 'Bearer ' + PAT, 'Content-Type': 'application/json' },
  body: JSON.stringify({ records: [record] })
});

// SMS notification to restaurant staff (skipped until TWILIO_TO is set)
if (TWILIO_TO) {
  const smsBody = 'New phone order #' + ticketId + ': ' + customerName + ' - ' + (location || 'pickup') + '\n' + orderText + '\nTotal: $' + estimatedTotal.toFixed(2) + '\nPickup: ' + pickupTime;
  const params = new URLSearchParams({ To: TWILIO_TO, From: TWILIO_FROM, Body: smsBody });
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.twilio.com/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
    headers: {
      Authorization: 'Basic ' + Buffer.from(TWILIO_SID + ':' + TWILIO_AUTH).toString('base64'),
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    body: params.toString()
  });
}

return [{
  json: {
    results: [{
      toolCallId,
      result: 'Order received for ' + customerName + '. Your ticket number is ' + ticketId + '. Ready in about 15 to 20 minutes.'
    }]
  }
}];
